function makeNotebook(name, pw, pd, texL, texR, coverColor) {
  const g = new THREE.Group(); g.name = name;
  const cover = new THREE.Mesh(new THREE.BoxGeometry(pw * 2 + 0.04, 0.012, pd + 0.03), new THREE.MeshLambertMaterial({ color: coverColor }));
  cover.name = 'cover'; cover.position.y = 0.006; g.add(cover);
  const stack = new THREE.Mesh(new THREE.BoxGeometry(pw * 2 - 0.01, 0.012, pd - 0.01), pageEdgeMat);
  stack.name = 'page-stack'; stack.position.y = 0.016; g.add(stack);
  for (const [side, tex] of [[-1, texL], [1, texR]]) {
    const pg = new THREE.Group(); pg.name = side < 0 ? 'page-left' : 'page-right';
    pg.position.set(side * 0.004, 0.0225, 0); pg.rotation.z = side * 0.035;
    const m = new THREE.Mesh(new THREE.PlaneGeometry(pw, pd), new THREE.MeshLambertMaterial({ map: tex }));
    m.rotation.x = -Math.PI / 2; m.position.x = side * pw / 2;
    pg.add(m); g.add(pg);
  }
  const spine = new THREE.Mesh(new THREE.BoxGeometry(0.008, 0.004, pd), spineMat); spine.name = 'spine';
  spine.position.y = 0.023; g.add(spine);
  g.traverse(o => { if (o.isMesh) { o.receiveShadow = true; o.castShadow = true; } });
