function placePencil(name, a, b, color) {
  const len = a.distanceTo(b);
  const g = new THREE.Group(); g.name = name;
  const bodyL = len * 0.82;
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, bodyL, 6), new THREE.MeshLambertMaterial({ color }));
  body.position.y = bodyL / 2; g.add(body);
  const tip = new THREE.Mesh(new THREE.ConeGeometry(0.016, len * 0.14, 6), woodTipMat); tip.position.y = bodyL + len * 0.07; g.add(tip);
  const lead = new THREE.Mesh(new THREE.ConeGeometry(0.006, len * 0.05, 6), leadMat); lead.position.y = bodyL + len * 0.115; g.add(lead);
  const er = new THREE.Mesh(new THREE.CylinderGeometry(0.016, 0.016, len * 0.06, 8), eraserMat); er.position.y = -len * 0.03; g.add(er);
  g.position.copy(a);
  g.quaternion.setFromUnitVectors(Y, b.clone().sub(a).normalize());
  g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
  pencils.add(g);
  return g;
}
