const KT = [0, 200, 400, 600, 800, 1000, 1200, 1400, 1500];
const TR = {
  // right character leans in, then tilts its face down toward the left one
  rdx:    [0, -0.06, -0.075, -0.07, -0.065, -0.06, -0.06, -0.06, 0],
  rdy:    [0, -0.01, -0.015, -0.025, -0.045, -0.06, -0.07, -0.07, 0],
  rpitch: [0, 0.02, 0.04, 0.07, 0.13, 0.18, 0.21, 0.22, 0],
  ryaw:   [0, 0.0, -0.02, -0.03, -0.04, -0.04, -0.04, -0.04, 0],
